def ccw(p, a, b):
    return (a[0] - p[0]) * (b[1] - p[1]) - (a[1] - p[1]) * (b[0] - p[0])

def point_in_triangle(p, a, b, c):
    d1 = ccw(p, a, b)
    d2 = ccw(p, b, c)
    d3 = ccw(p, c, a)
    has_positive, has_negative = False, False
    for d in (d1, d2, d3):
        if d > 0:
            has_positive = True
        elif d < 0:
            has_negative = True
        if d == 0:
            return True
    return not (has_positive and has_negative)
```

