def is_point_on_segment(p, a, b):
    x, y = p
    x1, y1 = a
    x2, y2 = b
    if x1 == x2:
        # Vertical segment, compare x-coordinate
        if x != x1:
            return False
        # Point lies on the vertical line, check if y is between the endpoints
        return min(y1, y2) <= y <= max(y1, y2)
    if y1 == y2:
        # Horizontal segment, compare y-coordinate
        if y != y1:
            return False
        # Point lies on the horizontal line, check x
        return min(x1, x2) <= x <= max(x1, x2)
    # Non-axial segment: check if p lies on the line and within the bounding box
    # Use dot product to check that the projection onto the segment lies between the endpoints
    u = x2 - x1, y2 - y1
    v = x - x1, y - y1
    dot1 = u[0] * v[0] + u[1] * v[1]
    dot2 = u[0] * u[0] + u[1] * u[1]
    if dot1 < 0 or dot1 > dot2:
        return False
    # Point lies between a and b on the line, confirm bounds
    return min(x1, x2) <= x <= max(x1, x2) and min(y1, y2) <= y <= max(y1, y2)
```

The bounding box check screens off segments coming from vertical or horizontal code; for non-axis-aligned segments the dot product ensures the point projects inside the segment before the final coordinate bounds confirm it lies on both dimensions.

