def polygon_edge(point, next_point, final_point):
    head = (next_point[0] - point[0], next_point[1] - point[1])
    tail = (final_point[0] - point[0], final_point[1] - point[1])
    return cross(head, tail)

def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    # Close the polygon by repeating the first point
    closed = points + [points[0]]
    sign = 0

    for i in range(n):
        a, b, c = closed[i], closed[i + 1], closed[i + 2]
        edge = polygon_edge(a, b, c)
        if edge == 0:
            # Three collinear points imply a degenerate polygon
            return False
        if sign == 0:
            sign = 1 if edge > 0 else -1
        elif (edge > 0 and sign < 0) or (edge < 0 and sign > 0):
            return False
    return True
