def equal_under_rotation(grid1, grid2):
    """Check whether the second 2D grid equals the first rotated by 0, 90, 180, or 270 degrees."""

    def rotate_90(grid):
        """Rotate a grid 90 degrees clockwise."""
        return list(zip(*grid[::-1]))

    def all_rotations(grid):
        """Generate the four rotations: 0, 90, 180, 270 degrees."""
        for i in range(4):
            yield grid
            grid = rotate_90(grid)

    for g in all_rotations(grid1):
        if g == grid2:
            return True
    return False
```

