def queue_with_capacity_serve(events, capacity):
    from collections import deque
    queue = deque()
    for event in events:
        if event[0] == 'arrive':
            queue.append(event[1])
        else:
            queue = deque(queue)
            kept = []
            while len(kept) < capacity and queue:
                kept.append(queue.popleft())
            queue = deque(kept)
    return list(queue)
