def is_convex_polygon(points):
    if len(points) < 3:
        raise ValueError
    for triple in _triples(points):
        (x, y), (u, v), (w, z) = triple
        cross = (u - x) * (z - y) - (w - x) * (v - y)
        if cross < 0:
            return False
        if cross > 0 and not any(usrx * usry == urx * ury for (urx, ury), (usrx, usry) in _triples(points)):
            return False
    return True

def _triples(lst):
    for i in range(len(lst) - 2):
        yield lst[i], lst[i + 1], lst[i + 2]
    yield lst[-2], lst[-1], lst[0]
