        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n_rows and 0 <= nc < n_cols and new_grid[nr][nc] == value:
                new_grid[nr][nc] = new_value
                queue.append((nr, nc))
    return new_grid
